// elan06fa_model: software model of the real ELAN06FA HID-over-I2C device.
//
// registers follow the standard HID-over-I2C layout and the ACPI _DSM answer
// (HID descriptor at 0x0001): report descriptor 0x0002, input 0x0003, output
// 0x0004, command 0x0005, data 0x0006. the descriptor bytes and the input and
// feature report lengths come from the real device and are generated by
// gen_elan06fa.py. (satoru)

#include <linux/kernel.h>
#include <linux/string.h>
#include <linux/i2c.h>

#include "kimpl/lx_kshim.h"
#include "elan06fa_report_descriptor.h"
#include "elan06fa_model.h"

#define ELAN_HID_DESC_REG   0x0001
#define ELAN_REPORT_REG     0x0002
#define ELAN_INPUT_REG      0x0003
#define ELAN_OUTPUT_REG     0x0004
#define ELAN_COMMAND_REG    0x0005
#define ELAN_DATA_REG       0x0006

#define OP_RESET       0x01
#define OP_GET_REPORT  0x02
#define OP_SET_REPORT  0x03
#define OP_SET_POWER   0x08

static u16 le16(const u8 *p)
{
    return (u16)(p[0] | ((u16)p[1] << 8));
}

static void put_le16(u8 *p, u16 v)
{
    p[0] = (u8)v;
    p[1] = (u8)(v >> 8);
}

static unsigned int report_len(unsigned int type, unsigned int id)
{
    unsigned int i;
    for (i = 0; i < ELAN06FA_REPORT_COUNT; i++) {
        if (elan06fa_reports[i].type == type && elan06fa_reports[i].id == id)
            return elan06fa_reports[i].len;
    }
    return 0;
}

void elan06fa_init(struct elan06fa_model *m, int irq)
{
    memset(m, 0, sizeof(*m));
    m->irq = irq;
    m->report_desc = elan06fa_report_desc;
    m->report_desc_len = ELAN06FA_REPORT_DESC_LEN;
    /* HID descriptor 1.0, 30 bytes, report desc at 2, input at 3, output at
     * 4, command at 5, data at 6, ELAN VID/PID. wMaxInputLength is the model
     * value 64; the real device's exact value is not exposed by sysfs. */
    put_le16(m->hid_desc + 0, 30);
    put_le16(m->hid_desc + 2, 0x0100);
    put_le16(m->hid_desc + 4, (u16)m->report_desc_len);
    put_le16(m->hid_desc + 6, ELAN_REPORT_REG);
    put_le16(m->hid_desc + 8, ELAN_INPUT_REG);
    put_le16(m->hid_desc + 10, 64);
    put_le16(m->hid_desc + 12, ELAN_OUTPUT_REG);
    put_le16(m->hid_desc + 14, 0);
    put_le16(m->hid_desc + 16, ELAN_COMMAND_REG);
    put_le16(m->hid_desc + 18, ELAN_DATA_REG);
    put_le16(m->hid_desc + 20, 0x04f3);
    put_le16(m->hid_desc + 22, 0x327e);
    put_le16(m->hid_desc + 24, 0x0100);
}

void elan06fa_queue_input(struct elan06fa_model *m, const u8 *report,
                          unsigned int len)
{
    if (len + 2 > sizeof(m->input))
        return;
    put_le16(m->input, (u16)(len + 2));
    memcpy(m->input + 2, report, len);
    m->input_len = len + 2;
    m->have_input = 1;
    if (m->irq_raise)
        m->irq_raise(m);
    else
        lx_irq_raise_soft((unsigned int)m->irq);
}

void elan06fa_queue_reset(struct elan06fa_model *m)
{
    memset(m->input, 0, 4);
    m->input_len = 2;
    m->have_input = 1;
    if (m->irq_raise)
        m->irq_raise(m);
    else
        lx_irq_raise_soft((unsigned int)m->irq);
}

static void build_feature(struct elan06fa_model *m, unsigned int id)
{
    unsigned int len = report_len(2, id);

    memset(m->get, 0, sizeof(m->get));
    m->get_len = 0;
    if (!len || len > sizeof(m->get))
        return;
    m->get[0] = (u8)id;
    if (id == 0x02) {
        /* contact count maximum 5, button type clickpad (0). */
        m->get[1] = 0x05;
    } else if (id == 0x03) {
        /* input mode touchpad (3), little endian. */
        m->get[1] = 0x03;
        m->get[2] = 0x00;
    }
    m->get_len = len;
    m->have_get = 1;
}

static void parse_command(struct elan06fa_model *m, const u8 *buf,
                          unsigned int len)
{
    unsigned int id, type, pos;
    u8 enc, op;

    if (len < 4)
        return;
    enc = buf[2];
    op = buf[3];
    id = enc & 0x0f;
    type = enc >> 4;
    if (id == 0x0f) {
        if (len < 5)
            return;
        id = buf[4];
        pos = 5;
    } else {
        pos = 4;
    }
    switch (op) {
    case OP_SET_POWER:
        if ((enc & 0x0f) == 0)
            m->power_ons++;
        break;
    case OP_RESET:
        m->resets++;
        elan06fa_queue_reset(m);
        break;
    case OP_GET_REPORT:
        if (pos + 2 > len)
            return;
        build_feature(m, id);
        break;
    case OP_SET_REPORT:
        if (pos + 4 > len)
            return;
        pos += 2; /* data register */
        {
            unsigned int size = le16(buf + pos);
            pos += 2;
            if (pos + size > len)
                size = len - pos;
            m->last_set_type = (int)type;
            m->last_set_id = (int)id;
            m->last_set_len = size;
            if (size > sizeof(m->last_set))
                size = sizeof(m->last_set);
            memcpy(m->last_set, buf + pos, size);
            m->set_reports++;
            if (type == 3 && id == 0x03 && size >= 3)
                m->device_mode = m->last_set[1] | (m->last_set[2] << 8);
        }
        break;
    default:
        break;
    }
}

static void fill_read(struct elan06fa_model *m, struct i2c_msg *msg)
{
    memset(msg->buf, 0, msg->len);
    if (m->have_get) {
        unsigned int n = 2 + m->get_len;
        if (n > msg->len)
            n = msg->len;
        put_le16(msg->buf, (u16)(2 + m->get_len));
        if (n > 2)
            memcpy(msg->buf + 2, m->get, n - 2);
        m->have_get = 0;
        return;
    }
    if (!m->have_input)
        return; /* zero length: reset sentinel / no data */
    {
        unsigned int n = m->input_len;
        if (n > msg->len)
            n = msg->len;
        memcpy(msg->buf, m->input, n);
    }
    m->have_input = 0;
    m->input_reads++;
    if (m->irq_deassert)
        m->irq_deassert(m);
}

int elan06fa_master_xfer(struct i2c_adapter *adap, struct i2c_msg *msgs, int num)
{
    struct elan06fa_model *m = adap->algo_data;
    int i;

    if (!m)
        return -EIO;
    for (i = 0; i < num; i++) {
        struct i2c_msg *msg = &msgs[i];
        if (msg->addr != ELAN06FA_I2C_ADDR)
            return -ENXIO;
        if (msg->flags & I2C_M_RD) {
            fill_read(m, msg);
            continue;
        }
        if (msg->len >= 2) {
            u16 reg = le16(msg->buf);
            if (reg == ELAN_HID_DESC_REG) {
                unsigned int n = msg->len - 2;
                if (n > sizeof(m->hid_desc))
                    n = sizeof(m->hid_desc);
                m->hid_desc_reads++;
                /* a write-only register read is not a thing; the read follows */
                (void)n;
            } else if (reg == ELAN_REPORT_REG) {
                m->report_desc_reads++;
            } else if (reg == ELAN_COMMAND_REG) {
                parse_command(m, msg->buf, msg->len);
            } else {
                /* input/output register write: nothing to do. */
            }
        }
    }
    /* reads that belong to a register read are the next message; the core
     * sends a 2-byte register write first and then a read, so handle it by
     * looking at the preceding write inside the same transfer. */
    for (i = 0; i < num; i++) {
        struct i2c_msg *msg = &msgs[i];
        if (!(msg->flags & I2C_M_RD) || i == 0 || msg->len == 0)
            continue;
        if (msgs[i - 1].flags & I2C_M_RD)
            continue;
        if (msgs[i - 1].len >= 2) {
            u16 reg = le16(msgs[i - 1].buf);
            if (reg == ELAN_HID_DESC_REG) {
                unsigned int n = msg->len;
                if (n > sizeof(m->hid_desc))
                    n = sizeof(m->hid_desc);
                memset(msg->buf, 0, msg->len);
                memcpy(msg->buf, m->hid_desc, n);
            } else if (reg == ELAN_REPORT_REG) {
                unsigned int n = msg->len;
                if (n > m->report_desc_len)
                    n = m->report_desc_len;
                memset(msg->buf, 0, msg->len);
                memcpy(msg->buf, m->report_desc, n);
            }
        }
    }
    return num;
}

// end (satoru)
